function Brand(){return <div className="brand"><span><Sprout/></span><b>مهرانا<small>رشد سالم، با عشق و آگاهی</small></b></div>}
function Landing({user}){return <div className="landing"><header className="public wrap"><Brand/><nav><a href="#features">امکانات</a><a href="#plans">اشتراک</a><a href="#about">درباره مهرانا</a><NavLink to="/library">آموزش‌ها</NavLink></nav><NavLink className="btn primary" to="/login">ورود به مهرانا <ArrowLeft size={16}/></NavLink></header><section className="hero wrap"><div><span className="eyebrow">همراه خانواده از تولد تا پنج‌سالگی</span><h1>رشد سالم،<br/><em>با عشق و آگاهی</em></h1><p>مهرانا کنار شماست تا مسیر تغذیه و رشد کودک را آگاهانه‌تر، منظم‌تر و آرام‌تر طی کنید؛ قدم‌به‌قدم و متناسب با سن فرزندتان.</p><NavLink className="btn primary" to="/login">شروع همراهی با مهرانا <ArrowLeft size={16}/></NavLink><NavLink className="btn outline preview-cta" to="/dashboard"><Sparkles size={16}/> مشاهده امکانات بدون ورود</NavLink><div className="trust"><ShieldCheck size={17}/> آموزش مبتنی بر منابع معتبر، با تأکید بر ایمنی کودک</div></div><div className="hero-art"><div className="sun"/><div className="orb"><Baby size={112}/></div><div className="float f1">♡ هر قدم، یک رشد</div><div className="float f2">✿ با آگاهی بزرگ شو</div></div></section><section id="features" className="features"><div className="wrap"><div className="center"><span className="eyebrow">همراهی در هر مرحله</span><h2>همه چیز برای مسیر تغذیه کودک</h2><p>از اولین روزهای شیردهی تا شکل‌گیری عادت‌های غذایی سالم.</p></div><div className="feature-grid">{[['♡','راهنمای شیردهی','آموزش‌های کاربردی برای شیردهی، دوشیدن و نگهداری شیر مادر.'],['◒','تغذیه با شیرخشک','نکات بهداشتی و ایمنی آماده‌سازی و نگهداری شیرخشک.'],['↗','پایش رشد','ثبت اندازه‌گیری‌ها و مشاهده روند تغییرات کودک.'],['✦','نقشه رشد و تکامل','مرور نقاط عطف حرکتی، زبانی، شناختی و اجتماعی کودک.'],['☾','دفترچه خواب','ثبت خواب شبانه و چرت‌های روزانه کودک.'],['♡','برنامه روزانه غذایی','الگوی وعده‌های متناسب با سن و اصول ایمنی غذا.']].map((x,i)=><article className="feature" key={x[1]}><div className={'fi c'+i}>{x[0]}</div><h3>{x[1]}</h3><p>{x[2]}</p></article>)}</div></div></section><section id="plans" className="plans-section"><div className="wrap"><div className="center"><span className="eyebrow">رشد مهرانا، قدم‌به‌قدم</span><h2>طرح‌های همراهی خانواده</h2><p>امکانات ضروری و راهنمای ایمنی رایگان می‌مانند؛ ابزارهای تکمیلی به‌تدریج اضافه می‌شوند.</p></div><PlanCards user={user}/></div></section><section id="about" className="about wrap"><div className="about-icon"><Baby size={64}/></div><div><span className="eyebrow">درباره مهرانا</span><h2>آگاهی، همراهی و آرامش در مسیر والدگری</h2><p>مهرانا ابزار ثبت و یادگیری است؛ جایگزین پزشک یا متخصص تغذیه کودک نیست. هدف ما کمک به تصمیم‌گیری آگاهانه و گفت‌وگوی بهتر با متخصصان است.</p></div></section><footer><Brand/><span>© مهرانا · رشد سالم، با عشق و آگاهی</span></footer></div>}
