 const [phone,setPhone]=useState(''),[code,setCode]=useState(''),[demoCode,setDemoCode]=useState(''),[step,setStep]=useState('phone'),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[agree,setAgree]=useState(false),[demoAgree,setDemoAgree]=useState(false),[cooldown,setCooldown]=useState(0);
 useEffect(()=>{if(cooldown<=0)return;const timer=setInterval(()=>setCooldown(value=>Math.max(0,value-1)),1000);return()=>clearInterval(timer)},[cooldown>0]);
 async function requestCode(e){e.preventDefault();setError('');setNotice('');setBusy(true);try{const response=await fetch('/api/auth/request-otp',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({phone})}),result=await response.json();if(!response.ok)throw new Error(result.error||'ارسال کد انجام نشد.');setStep('code');setCooldown(45);setNotice('کد ورود فرستاده شد.')}catch(err){setError(err.message||'ارتباط با سرور برقرار نشد.')}finally{setBusy(false)}}
