 useEffect(()=>{document.title='مدیریت محتوا | مهرانا';let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement('meta');robots.name='robots';document.head.appendChild(robots)}robots.content='noindex,nofollow'},[]);
